,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'This page provides a faceted search experience for support tickets using the <strong>EBA_DEMO_JSON_SUPPORT_TICKET</strong> JSON source. Users can filter tickets by status, priority, and creation date range, with results displayed as cards and highlig'
||'hted using color-coded status badges.',
'</p>',
'',
'<p>',
'To get started, use the faceted search filters to refine the displayed tickets. Each card includes a <strong>Details</strong> button that opens the full support ticket information.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(404343029961238343)
,p_plug_name=>'Search Results'
,p_region_name=>'tickets_card'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleA'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>40
,p_location=>'JSON_COLLECTION'
,p_document_source_id=>wwv_flow_imp.id(296294017053623558661)
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.c_id,',
'       s.title,',
'       s.status,',
'       s.priority,',
'       s.ticket_id,',
'       s.created_at2,',
'       s.description,',
'       s.comments,',
'       s.resolution,',
'       s.updated_at,',
'       s.customer_id,',
'       s.concern_order_id,',
'       s.concern_store_id,',
'       s.concern_product_id,',
'       c.full_name,',
'       p.product_name,',
'       st.store_name,',
'       case ',
'         when upper(s.status) = ''OPEN''     then ''u-color-9''',
'         when upper(s.status) = ''RESOLVED'' then ''u-color-5''',
'         when upper(s.status) = ''PENDING''  then ''u-color-22''',
'         else ''u-color-14''',
'       end as badge_class',
'  from #APEX$SOURCE_DATA# s,',
'       eba_demo_json_customers c,',
'       eba_demo_json_products  p,',
'       eba_demo_json_stores    st',
' where c.customer_id  (+) = s.customer_id',
'   and p.product_id   (+) = s.concern_product_id',
'   and st.store_id    (+) = s.concern_store_id'))
,p_source_post_processing=>'SQL'
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_ai_enabled=>false
);
