,p_process_name=>'Load additional JSON'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_uploaded_file blob;',
'    l_uploaded_text clob;',
'begin',
'    select blob_content',
'      into l_uploaded_file',
'      from apex_application_temp_files',
'     where name = :P502_JSON_FILE;',
'',
'    l_uploaded_text := apex_util.blob_to_clob( l_uploaded_file );',
'',
'    insert into eba_demo_json_support_ticket ( data )',
'    select rtrim( t.column_value, chr( 13 ) )',
'      from table( apex_string.split_clobs( l_uploaded_text, chr( 10 ) ) ) t',
'     where rtrim( t.column_value, chr( 13 ) ) is not null;',
'',
'    :P502_LOADED_ROW_COUNT := sql%rowcount;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(296291382419911231752)
,p_process_success_message=>'&P502_LOADED_ROW_COUNT. JSON documents loaded into the JSON Collection Table.'
,p_internal_uid=>3780158475340711
);
